      if (uVar2 == 1) {
        iVar4 = iVar4 + 1;
      }
      else if (param_1[iVar4] == '/') {
        uVar2 = uVar2 & 0xffffff00 | (uint)(byte)param_1[iVar4 + 1] | 0x20;
        if ((char)uVar2 == 'w') {
          IsWindowedMode = 1;
        }
        else if ((char)uVar2 == 'f') {
