Below is a tiny, self-contained program that

1. installs a handler for SIGALRM that does nothing (so the signal is delivered but the system call is not automatically restarted),
2. calls alarm(2) so the signal arrives while we are blocked inside read(),
3. retries the read() when it fails with errno == EINTR.

Compile it, run it and do not type anything for at least two seconds; you will see read() being interrupted and then immediately re-issued.

```c
/*
 * eintr_read.c
 *
 * Demonstrates a blocking read(2) that is interrupted by a signal
 * and shows the canonical EINTR handling pattern.
 */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <stdlib.h>

/* --- Signal handler ----------------------------------------------------- */
static void
sigalrm_handler(int sig)
{
    (void)sig;           /* unused */
    /* Nothing to do – we only want to interrupt read(). */
}

/* ------------------------------------------------------------------------ */
int
main(void)
{
    struct sigaction sa;
    char  buf[128];
    ssize_t n;

    /* Install handler for SIGALRM without SA_RESTART so read() gets EINTR. */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigalrm_handler;
    sigemptyset(&sa.sa_mask);
    /* no SA_RESTART here on purpose */
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    puts("About to block in read(); SIGALRM will arrive in 2 s …");
    alarm(2);

    for (;;) {
        n = read(STDIN_FILENO, buf, sizeof(buf));

        if (n == -1) {
            if (errno == EINTR) {          /* <-- the interesting part */
                fprintf(stderr,
                        "read() was interrupted by signal, retrying …\n");
                continue;                  /* just try again */
            }
            /* Any other error is fatal. */
            perror("read");
            return EXIT_FAILURE;
        }

        if (n == 0)        /* EOF on stdin */
            break;

        /* Echo whatever we got. */
        if (write(STDOUT_FILENO, buf, (size_t)n) == -1) {
            perror("write");
            return EXIT_FAILURE;
        }
    }

    puts("\nEnd of file – exiting.");
    return EXIT_SUCCESS;
}
```

Build & run

```
$ gcc -Wall -Wextra -O2 eintr_read.c -o eintr_read
$ ./eintr_read
About to block in read(); SIGALRM will arrive in 2 s …
read() was interrupted by signal, retrying …
```

After the `alarm` expires, `read()` returns `-1`, `errno` is set to `EINTR`, the program prints the message and immediately jumps back into the loop, re-issuing `read()` just as the POSIX documentation recommends.

Below is a compact, self-contained example that shows TWO common ways to “read network packets on port 888” in C++:

• TCP – accept a connection and `read()` the byte stream  
• UDP – simply `recvfrom()` datagrams that arrive on the port

Pick the part you need, or leave both in and choose at run-time with a command-line switch.

```cpp
/*
 *  server888.cpp
 *
 *  Build  : g++ -std=c++17 -Wall -O2 server888.cpp -o server888
 *  Run    : ./server888   or   ./server888 udp
 *
 *  By default it starts a TCP server; pass the word "udp" to start
 *  the UDP variant instead.  The program just dumps everything it
 *  receives to stdout.
 *
 *  Tested on Linux; requires standard BSD sockets headers.
 */

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <cstring>
#include <iostream>

constexpr int PORT         = 888;      // port we listen on
constexpr size_t BUFSIZE   = 4096;     // read buffer

//--------------------------------------------------------------------
// Helper: set SO_REUSEADDR so we can restart quickly during testing
//--------------------------------------------------------------------
static void setReuseAddr(int fd)
{
    int yes = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes)) < 0)
        std::perror("setsockopt(SO_REUSEADDR)");
}

//--------------------------------------------------------------------
// TCP server – accept 1 connection at a time and dump what it sends
//--------------------------------------------------------------------
void runTcpServer()
{
    int listenFd = socket(AF_INET, SOCK_STREAM, 0);
    if (listenFd < 0)
        { std::perror("socket"); return; }

    setReuseAddr(listenFd);

    sockaddr_in addr{};
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons(PORT);

    if (bind(listenFd, (sockaddr*)&addr, sizeof(addr)) < 0)
        { std::perror("bind"); return; }

    if (listen(listenFd, 10) < 0)      // backlog = 10
        { std::perror("listen"); return; }

    std::cout << "[TCP] Listening on port " << PORT << " ...\n";

    while (true)
    {
        sockaddr_in peer{};
        socklen_t peerLen = sizeof(peer);
        int connFd = accept(listenFd, (sockaddr*)&peer, &peerLen);
        if (connFd < 0)
            { std::perror("accept"); continue; }

        char peerIp[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &peer.sin_addr, peerIp, sizeof(peerIp));
        std::cout << "[TCP] Connection from " << peerIp
                  << ":" << ntohs(peer.sin_port) << '\n';

        char buf[BUFSIZE];
        ssize_t n;
        while ((n = read(connFd, buf, sizeof(buf))) > 0)
            std::cout.write(buf, n);

        if (n == 0)
            std::cout << "\n[TCP] peer closed connection\n";
        else
            std::perror("read");

        close(connFd);
    }
}

//--------------------------------------------------------------------
// UDP server – receive datagrams forever and dump their payload
//--------------------------------------------------------------------
void runUdpServer()
{
    int sockFd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockFd < 0)
        { std::perror("socket"); return; }

    setReuseAddr(sockFd);

    sockaddr_in addr{};
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons(PORT);

    if (bind(sockFd, (sockaddr*)&addr, sizeof(addr)) < 0)
        { std::perror("bind"); return; }

    std::cout << "[UDP] Listening on port " << PORT << " ...\n";

    char buf[BUFSIZE];
    sockaddr_in peer{};
    socklen_t   peerLen;

    while (true)
    {
        peerLen = sizeof(peer);
        ssize_t n = recvfrom(sockFd, buf, sizeof(buf), 0,
                             (sockaddr*)&peer, &peerLen);
        if (n < 0)
        {
            std::perror("recvfrom");
            continue;
        }

        char peerIp[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &peer.sin_addr, peerIp, sizeof(peerIp));
        std::cout << "\n[UDP] Packet from " << peerIp
                  << ":" << ntohs(peer.sin_port) << "  (" << n << " bytes)\n";
        std::cout.write(buf, n);
        std::cout.flush();
    }
}

//--------------------------------------------------------------------
// main: choose TCP or UDP based on argv[1]
//--------------------------------------------------------------------
int main(int argc, char* argv[])
{
    if (argc > 1 && std::strcmp(argv[1], "udp") == 0)
        runUdpServer();
    else
        runTcpServer();
    return 0;
}
```

How to use:

1. Build  
   `g++ -std=c++17 -Wall server888.cpp -o server888`

2. TCP mode (default)  
   ```
   ./server888
   # In another shell:
   echo "hello world" | nc 127.0.0.1 888
   ```

3. UDP mode  
   ```
   ./server888 udp
   # In another shell:
   echo "hi via udp" | nc -u 127.0.0.1 888
   ```

The program prints every byte it receives, demonstrating how to “read network packets from a socket on port 888” in C++.

Copy–paste the code below on the **Path** property of any shape-layer.  
It builds a 500 px × 500 px square whose TOP-RIGHT corner is rounded;  
change the two numbers on the first two lines if you want a different size or radius.

```javascript
//--------------------------------------------------------
// 500 x 500 square   – only the top-right corner rounded
//--------------------------------------------------------
side    = 500;   // overall width / height  (px)
radius  = 60;    // roundness of the top-right corner (px)

//--------------------------------------------------------
h  = side/2;                       // half the side
r  = Math.min(radius, h);          // make sure radius is legal
k  = r*0.5522847498307936;         // Bézier “magic” for a quarter circle

// vertices ------------------------------------------------
verts = [
        [-h, -h],        // 0  top-left
        [ h-r, -h],      // 1  start of rounded corner
        [ h,  -h+r],     // 2  end   of rounded corner
        [ h,   h],       // 3  bottom-right
        [-h,  h]         // 4  bottom-left
        ];

// in- & out tangents -------------------------------------
inTang  = [
          [0,0],         // to 0
          [0,0],         // to 1
          [0,-k],        // to 2  (quarter-circle control)
          [0,0],         // to 3
          [0,0]          // to 4
          ];

outTang = [
          [0,0],         // from 0
          [k,0],         // from 1  (quarter-circle control)
          [0,0],         // from 2
          [0,0],         // from 3
          [0,0]          // from 4
          ];

// build and return the closed path -----------------------
createPath(verts, inTang, outTang, true);
```

Explanation of the important bits  
• `k = r*0.5522847498…` is the standard factor that lets two Bézier handles approximate a perfect quarter-circle.  
• Only points 1 → 2 carry handles; everything else is a straight line, so their tangents are `[0,0]`.  
• The path is centred on the layer’s anchor; move or scale the layer to position/size it in comp space.

Below is a compact but complete example that shows one possible way of doing what you asked for with the pure Open-XML SDK 2.x (no 3rd-party libraries).

Assumptions / limitations
•	The SDK does not “understand” pages.  
  A page is therefore treated as everything up to the next manual page break  
  (<w:br w:type="page"/>) or the next section break.  
  If your template is split in another way you have to adapt the
  TrimAfterPage method.  
•	The code handles pictures that live in the MainDocumentPart
  (the usual <w:drawing>/<a:blip> case).  
  If you also have OLE objects, embedded packages, SmartArt, … the same
  copy-logic must be added for them, too.  
•	Styles, fonts, numbering, etc. are kept from the first file.
  The second file is appended “as is”; styles that do not exist in the first
  file will be duplicated with new ids.  
•	Error handling and logging were removed for readability.

Add a reference to DocumentFormat.OpenXml.dll and put the 3 helpers that follow
into the same class.

```C#
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using A = DocumentFormat.OpenXml.Drawing;

public static class WordMerger
{
    /// <summary>
    /// Merges two *.docx files.
    ///  – From templatePath the first two pages + headers/footers + design are kept.
    ///  – From appendPath only the body content and the glossary are taken.
    ///  – Pictures that occur in the body are copied as well.
    /// </summary>
    public static void Merge(
        string templatePath,
        string appendPath,
        string resultPath)
    {
        //----------------------------------------------------------------------
        // 1. Create result file by copying the template -----------------------
        //----------------------------------------------------------------------
        File.Copy(templatePath, resultPath, true);

        using (WordprocessingDocument resultDoc =
               WordprocessingDocument.Open(resultPath, true))
        using (WordprocessingDocument secondDoc =
               WordprocessingDocument.Open(appendPath, false))
        {
            MainDocumentPart resultMain = resultDoc.MainDocumentPart;
            MainDocumentPart secondMain = secondDoc.MainDocumentPart;

            //------------------------------------------------------------------
            // 2. Keep only the first 2 pages of the template -------------------
            //------------------------------------------------------------------
            TrimAfterPage(resultMain, 2);

            //------------------------------------------------------------------
            // 3. Copy glossary from the second file ---------------------------
            //------------------------------------------------------------------
            CopyGlossary(secondDoc, resultDoc);

            //------------------------------------------------------------------
            // 4. Append body of the second file (with pictures) ---------------
            //------------------------------------------------------------------
            AppendBodyWithImages(secondMain, resultMain);
        }
    }

    // -----------------------------------------------------------------------
    // Helper 1 : remove everything that comes after <wantedPages> pages
    // -----------------------------------------------------------------------
    private static void TrimAfterPage(MainDocumentPart mainPart, int wantedPages)
    {
        Body oldBody = mainPart.Document.Body;
        Body newBody = new Body();
        int seenPageBreaks = 0;

        foreach (OpenXmlElement element in oldBody.Elements())
        {
            // Count manual page breaks
            if (element.Descendants<Break>().Any(b => b.Type == BreakValues.Page))
                seenPageBreaks++;

            // Count section breaks as well (every section starts a new page)
            if (element is Paragraph p && p.ParagraphProperties?.SectionProperties != null)
                seenPageBreaks++;

            newBody.Append(element.CloneNode(true));

            if (seenPageBreaks >= wantedPages)
                break;
        }

        // Preserve the last section properties from the original body
        SectionProperties sect = oldBody.Elements().LastOrDefault()
                                       ?.Descendants<SectionProperties>()
                                       .LastOrDefault();
        if (sect != null && newBody.Descendants<SectionProperties>().LastOrDefault() == null)
            newBody.Append(sect.CloneNode(true));

        mainPart.Document.Body.RemoveAllChildren();
        mainPart.Document.Body.Append(newBody.Elements());
    }

    // -----------------------------------------------------------------------
    // Helper 2 : copy glossary (BuildingBlocksPart) --------------------------
    // -----------------------------------------------------------------------
    private static void CopyGlossary(WordprocessingDocument src,
                                     WordprocessingDocument dst)
    {
        if (src.MainDocumentPart.GlossaryDocumentPart == null)
            return;

        GlossaryDocumentPart srcGlossary = src.MainDocumentPart.GlossaryDocumentPart;
        GlossaryDocumentPart dstGlossary =
            dst.MainDocumentPart.AddNewPart<GlossaryDocumentPart>();

        dstGlossary.FeedData(srcGlossary.GetStream(FileMode.Open, FileAccess.Read));
    }

    // -----------------------------------------------------------------------
    // Helper 3 : append body and copy every image the new paragraphs reference
    // -----------------------------------------------------------------------
    private static void AppendBodyWithImages(MainDocumentPart source,
                                             MainDocumentPart destination)
    {
        // We need a map oldRid -> newRid for every part we duplicate
        Dictionary<string, string> relIdMap = new Dictionary<string, string>();

        foreach (OpenXmlElement element in source.Document.Body.Elements())
        {
            // Clone so we can safely manipulate relationship ids
            OpenXmlElement imported = element.CloneNode(true);

            // --- images ------------------------------------------------------
            foreach (A.Blip blip in imported.Descendants<A.Blip>())
            {
                string oldRid = blip.Embed?.Value;
                if (oldRid == null) continue;

                // Re-use mapping if we already copied that picture
                if (!relIdMap.TryGetValue(oldRid, out string newRid))
                {
                    ImagePart oldPart = (ImagePart)source.GetPartById(oldRid);
                    ImagePart newPart = destination.AddImagePart(oldPart.ContentType);

                    using (Stream sOld = oldPart.GetStream(),
                           sNew = newPart.GetStream(FileMode.Create))
                        sOld.CopyTo(sNew);

                    newRid = destination.GetIdOfPart(newPart);
                    relIdMap[oldRid] = newRid;
                }

                blip.Embed.Value = newRid;
            }

            destination.Document.Body.Append(imported.CloneNode(true));
        }
    }
}
```

How to use it:

```C#
WordMerger.Merge(
    templatePath : @"c:\Docs\Template.docx",
    appendPath   : @"c:\Docs\Second.docx",
    resultPath   : @"c:\Docs\Merged.docx");
```

What happens inside

1. A physical copy of the first file becomes the result.  
   Therefore all design information that lives in parts
   (styles.xml, fontTable.xml, header/footer, theme, numbering, …)
   is already present.

2. TrimAfterPage keeps only the very first two “pages”
   (detected by manual page breaks / section breaks).

3. The BuildingBlocksPart (glossary) of the second file is duplicated into
   the result file so that AutoText, Quick-Parts, etc. are preserved.

4. Every paragraph/run/table/… of the second document’s `body` is cloned,
   added to the result body, and all picture parts it references are copied.
   Each picture receives a fresh relationship id in the destination document
   and the XML is patched accordingly.

You can extend the AppendBodyWithImages method in the exact same fashion
to cover other related parts (charts, embedded packages, custom XML, …)
if you need them.

