package com.demo.reverb

/**
 * Kotlin façade for the native engine.
 * Simply call  start()  and  stop()  from your activity.
 */
object MicReverb {

    init {
        System.loadLibrary("mic_reverb")   // <── built by CMake/NDK
    }

    external fun create(sampleRate: Int, framesPerBurst: Int): Long
    external fun start(engineHandle: Long)
    external fun stop(engineHandle: Long)
    external fun setWetDry(engineHandle: Long, wet: Float)          // 0.0 … 1.0
    external fun shutdown(engineHandle: Long)
}

/**
 * Convenience wrapper that hides the native handle.
 */
class ReverbSession(private val sampleRate: Int, private val framesPerBurst: Int) {

    private var nativePtr: Long = 0

    fun start() {
        nativePtr = MicReverb.create(sampleRate, framesPerBurst)
        MicReverb.start(nativePtr)
    }

    fun setWetDry(value: Float) = MicReverb.setWetDry(nativePtr, value)

    fun stop() {
        MicReverb.stop(nativePtr)
        MicReverb.shutdown(nativePtr)
        nativePtr = 0
    }
}

