#pragma once
#include <oboe/Oboe.h>
#include <vector>

class ReverbEngine : public oboe::AudioStreamCallback {
public:
    explicit ReverbEngine(int32_t sampleRate, int32_t framesPerBurst);
    ~ReverbEngine();

    void start();
    void stop();
    void setWetDry(float wet);

    /* oboe callback */
    oboe::DataCallbackResult
    onAudioReady(oboe::AudioStream *stream,
                 void *audioData, int32_t numFrames) override;

private:
    void createStreams();

    /* very small Schroeder reverb ---------------------------- */
    struct Comb {
        std::vector<float> buf; int idx = 0; float fb = .75f;
        void init(int d, float f) { buf.assign(d, 0); fb = f; }
        float process(float x) {
            float y = buf[idx];
            buf[idx] = x + y * fb;
            idx++; if (idx >= (int)buf.size()) idx = 0;
            return y;
        }
    };
    struct AllPass {
        std::vector<float> buf; int idx = 0; float g = .7f;
        void init(int d, float gg) { buf.assign(d, 0); g = gg; }
        float process(float x){
            float y = buf[idx];
            buf[idx] = x + y * g;
            idx++; if (idx >= (int)buf.size()) idx = 0;
            return -x + y;
        }
    };
    class Reverb {
        std::vector<Comb> comb;
        std::vector<AllPass> ap;
    public:
        void init(int sr){
            int combD[] ={1737,1601,1491,1422};
            int apD[]   ={ 556, 441};
            for(int d:combD){ Comb c; c.init(d*sr/48000, .773f); comb.push_back(c);}
            for(int d:apD){ AllPass a; a.init(d*sr/48000, .7f); ap.push_back(a);}
        }
        float process(float x){
            float y=0; for(auto& c:comb) y += c.process(x);
            for(auto& a:ap) y = a.process(y);
            return y*0.3f;   // output gain
        }
    } mReverb;

    std::shared_ptr<oboe::AudioStream> mIn, mOut;
    int32_t mSampleRate = 48000, mFramesPerBurst = 256;
    float mWet = 0.5f;
};

3-b  ReverbEngine.cpp
─────────────────────
#include "ReverbEngine.h"
#include <android/log.h>
#define LOG(...)  __android_log_print(ANDROID_LOG_INFO,"Reverb",__VA_ARGS__)

ReverbEngine::ReverbEngine(int32_t sr, int32_t fpb)
        : mSampleRate(sr), mFramesPerBurst(fpb) {
    mReverb.init(sr);
    createStreams();
}
ReverbEngine::~ReverbEngine() { stop(); }

void ReverbEngine::createStreams() {
    oboe::AudioStreamBuilder inBuilder, outBuilder;

    inBuilder.setDirection(oboe::Direction::Input)
             .setSampleRate(mSampleRate)
             .setFormat(oboe::AudioFormat::Float)
             .setPerformanceMode(oboe::PerformanceMode::LowLatency)
             .setSharingMode(oboe::SharingMode::Exclusive);

    outBuilder.setDirection(oboe::Direction::Output)
              .setSampleRate(mSampleRate)
              .setFormat(oboe::AudioFormat::Float)
              .setChannelCount(1)
              .setPerformanceMode(oboe::PerformanceMode::LowLatency)
              .setCallback(this);

    inBuilder.openStream(mIn);
    outBuilder.openStream(mOut);

    mIn->setBufferSizeInFrames(mFramesPerBurst);
    mOut->setBufferSizeInFrames(mFramesPerBurst);
}

void ReverbEngine::start() {
    mIn->requestStart();
    mOut->requestStart();
}
void ReverbEngine::stop() {
    if (mOut) mOut->requestStop();
    if (mIn)  mIn->requestStop();
}
void ReverbEngine::setWetDry(float w) { mWet = std::max(0.f, std::min(1.f, w)); }

oboe::DataCallbackResult
ReverbEngine::onAudioReady(oboe::AudioStream *stream,
                           void *audioData, int32_t numFrames) {

    auto *out = static_cast<float *>(audioData);
    static float inBuf[1024];
    int32_t read = mIn->read(inBuf, numFrames, 0);   // non-blocking
    if (read < numFrames) memset(inBuf + read, 0, (numFrames - read)*sizeof(float));

    for (int i = 0; i < numFrames; ++i) {
        float dry = inBuf[i];
        float wet = mReverb.process(dry);
        out[i] = dry * (1 - mWet) + wet * mWet;
    }
    return oboe::DataCallbackResult::Continue;
}

