Below is a minimal, self-contained example that shows how you can build a *completely local* VPN on Android (API 21+) whose only job is to drop packets that are destined for IP addresses you consider “blocked”.  
The parts that are **absolutely necessary** for a working prototype are included; real-world NAT / TCP state-machine / MTU handling etc. are **far** more complicated and are intentionally left out or greatly simplified.

Files:  

 • app/src/main/java/.../MainActivity.kt  
 • app/src/main/java/.../LocalFilterVpnService.kt  

────────────────────────── MainActivity.kt
```kotlin
package com.example.localfiltervpn

import android.app.Activity
import android.content.Intent
import android.net.VpnService
import android.os.Bundle
import android.widget.Button
import android.widget.Toast

class MainActivity : Activity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        val btn = Button(this).apply { text = "Start / Stop VPN" }
        setContentView(btn)

        btn.setOnClickListener {
            // Ask the framework for VPN permission
            val intent = VpnService.prepare(this)
            if (intent != null) {
                startActivityForResult(intent, REQ_PREPARE_VPN)
            } else {
                // Already prepared
                onActivityResult(REQ_PREPARE_VPN, RESULT_OK, null)
            }
        }
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == REQ_PREPARE_VPN && resultCode == RESULT_OK) {
            val srvIntent = Intent(this, LocalFilterVpnService::class.java)
            startService(srvIntent)
            Toast.makeText(this, "VPN started", Toast.LENGTH_SHORT).show()
        }
    }

    companion object {
        private const val REQ_PREPARE_VPN = 100
    }
}
```

────────────────────────── LocalFilterVpnService.kt
```kotlin
package com.example.localfiltervpn

import android.app.PendingIntent
import android.content.Intent
import android.net.VpnService
import android.os.ParcelFileDescriptor
import android.util.Log
import java.io.FileInputStream
import java.io.FileOutputStream
import java.net.Inet4Address
import java.net.InetAddress
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.atomic.AtomicBoolean
import kotlin.concurrent.thread

class LocalFilterVpnService : VpnService() {

    private var tunFd: ParcelFileDescriptor? = null
    private val running = AtomicBoolean(false)

    // -------------  YOUR BLACK LIST  -------------
    private val blockedDestinations = hashSetOf(
        "8.8.8.8",
        "1.2.3.4"
    )
    // ---------------------------------------------

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        if (running.get()) return START_STICKY      // already running

        tunFd = createTunInterface()
        if (tunFd == null) {
            stopSelf()
            return START_NOT_STICKY
        }

        running.set(true)
        startPacketLoop(tunFd!!)
        return START_STICKY
    }

    override fun onDestroy() {
        super.onDestroy()
        running.set(false)
        tunFd?.close()
    }

    /* ------------------------------------------------------------------ */
    /*              T U N  –  I N T E R F A C E  C R E A T I O N          */
    /* ------------------------------------------------------------------ */
    private fun createTunInterface(): ParcelFileDescriptor? {
        val builder = Builder()

        builder.setSession("Local-IP-Filter")
            .setBlocking(true)                     // Let read() / write() block
            .addAddress("10.0.0.2", 32)            // Dummy address inside VPN
            .addRoute("0.0.0.0", 0)                // Intercept EVERYTHING

        // Optional: show a "vpn" notification that re-opens MainActivity
        val intent = PendingIntent.getActivity(
            this, 0, Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE
        )
        builder.setConfigureIntent(intent)

        return try {
            builder.establish()
        } catch (e: Exception) {
            Log.e(TAG, "Unable to establish VPN", e)
            null
        }
    }

    /* ------------------------------------------------------------------ */
    /*                   P A C K E T  L O O P  (single thread)            */
    /* ------------------------------------------------------------------ */
    private fun startPacketLoop(tun: ParcelFileDescriptor) {
        thread(name = "local-filter-vpn") {
            val input = FileInputStream(tun.fileDescriptor)
            val output = FileOutputStream(tun.fileDescriptor)

            val packet = ByteArray(32767)
            val buf = ByteBuffer.wrap(packet)
            buf.order(ByteOrder.BIG_ENDIAN)

            while (running.get()) {
                try {
                    val length = input.read(packet)
                    if (length <= 0) continue

                    buf.clear()
                    buf.limit(length)

                    // ---------- IPv4 ONLY -----------
                    if (!isIPv4(buf)) continue   // Ignore IPv6 here
                    val dst = ipv4Destination(buf)

                    if (isBlocked(dst)) {
                        Log.i(TAG, "Blocked -> $dst")
                        // drop (do NOT forward)
                        continue
                    }

                    // Allowed: just "reflect" back to the OS so that the stack
                    // proceeds normally.  For a *real* VPN you would have to
                    // open sockets towards the Internet here and do NAT, but
                    // for demonstration purposes bouncing the packet back to
                    // the kernel is enough.
                    output.write(packet, 0, length)

                } catch (e: Exception) {
                    Log.e(TAG, "I/O error", e)
                    break
                }
            }

            Log.i(TAG, "Packet loop stopped")
            stopSelf()
        }
    }

    /* ------------------------------------------------------------------ */
    /*                       H E L P E R S                                */
    /* ------------------------------------------------------------------ */
    private fun isBlocked(addr: InetAddress): Boolean =
        blockedDestinations.contains(addr.hostAddress)

    private fun isIPv4(buf: ByteBuffer): Boolean =
        (buf.get(0).toInt() shr 4) == 4          // first nibble == 4

    private fun ipv4Destination(buf: ByteBuffer): Inet4Address {
        val dst = ByteArray(4)
        buf.position(16)                         // 16-19 = destination
        buf.get(dst)
        return InetAddress.getByAddress(dst) as Inet4Address
    }

    companion object {
        private const val TAG = "LocalFilterVpn"
    }
}
```

How it works (quick recap)

1. The `Builder` creates a **TUN** interface and tells Android that *all* routes (`0.0.0.0/0`) now go through that interface.  
2. The service reads raw IP packets coming *from* the device on that TUN.  
3. Each packet is inspected: if its destination IP is on our blacklist we silently throw it away.  
4. Otherwise we `write()` the exact same bytes back into the TUN FD. Writing the packet “south-north” like that effectively gives it back to Android’s TCP/IP stack, and because we called `setBlocking(true)` everything still behaves synchronously for the app that generated the traffic.

Important limitations of this toy example

• Only IPv4 packets are parsed.  
• No NAT / transport-layer proxying is done; therefore the VPN is *not* a true tunnel to the Internet but rather a local packet filter.  
• Fragmentation, TCP MSS adjustments, MTU, checksums, etc. are glossed over.  
• For anything beyond simple dropping or logging you need a fully-featured user-space TCP/UDP stack (see projects like Toy-VPN, NetGuard, WireGuard-go-Android, etc.).

Still, this is all the boiler-plate you need to start experimenting with destination-IP-based filtering using Android’s VpnService API in Kotlin.

Below is a pragmatic, “from-scratch” walk-through for building a tiny, self–contained Kubernetes-log client with nothing except the JDK (11+) HTTP client.  
Feel free to copy‐paste the classes; after that you can refactor/package them into a real library.

────────────────────────────────────────────────────────────────────────
1. How the Kubernetes log API works
────────────────────────────────────────────────────────────────────────
GET /api/v1/namespaces/{namespace}/pods/{pod}/log  
Important query parameters

• container=<name>          – choose a specific container  
• follow=true               – keep the connection open and stream  
• previous=true             – grab the log of the previous container instance  
• sinceSeconds=<int> / sinceTime=<RFC3339>  
• tailLines=<int> / limitBytes=<int>  
• timestamps=true           – prepend each line with an RFC3339 timestamp  

The server simply returns text/plain; a “follow=true” request never ends
(HTTP/1.1 chunked transfer, not websocket).  
So you only need an InputStream and a line parser.

────────────────────────────────────────────────────────────────────────
2. Dealing with authentication & TLS
────────────────────────────────────────────────────────────────────────
Inside a pod  
  • Host:  https://kubernetes.default.svc  
  • Token: /var/run/secrets/kubernetes.io/serviceaccount/token  
  • CA:    /var/run/secrets/kubernetes.io/serviceaccount/ca.crt  

Outside the cluster  
  • Parse ~/.kube/config and pick the current-context (host, user, certs, token).  
  • Almost all clusters use a self-signed or private CA → you must feed that CA
    into an SSLContext.

────────────────────────────────────────────────────────────────────────
3. Minimal data classes
────────────────────────────────────────────────────────────────────────
LogOptions.java
```
public record LogOptions(
        boolean follow,
        boolean previous,
        Integer sinceSeconds,
        Integer tailLines,
        boolean timestamps) {

    public String toQuery() {
        var sb = new StringBuilder();
        if (follow)       sb.append("&follow=true");
        if (previous)     sb.append("&previous=true");
        if (sinceSeconds != null) sb.append("&sinceSeconds=").append(sinceSeconds);
        if (tailLines != null)    sb.append("&tailLines=").append(tailLines);
        if (timestamps)   sb.append("&timestamps=true");
        return sb.toString();
    }

    public static LogOptions follow() {   // convenience factory
        return new LogOptions(true,false,null,null,false);
    }
}
```

KubeConfig.java – extremely trimmed; reads token & CA file from either
kube-config or in-cluster files.

```
public final class KubeConfig {
    public final String host;   // "https://..."
    public final String token;  // Bearer token
    public final Path   caCert; // path to PEM file

    /* ---- constructors ---- */
    public static KubeConfig inCluster() throws IOException {
        return new KubeConfig(
            "https://kubernetes.default.svc",
            Files.readString(Path.of("/var/run/secrets/kubernetes.io/serviceaccount/token")),
            Path.of("/var/run/secrets/kubernetes.io/serviceaccount/ca.crt"));
    }

    public static KubeConfig fromUserHome() throws IOException {
        // extremely naive parser – just proves the idea
        Path kubeCfg = Path.of(System.getProperty("user.home"), ".kube","config");
        List<String> lines = Files.readAllLines(kubeCfg);
        String apiServer = null, token=null, ca=null;
        for (String l: lines) {
            l = l.trim();
            if (l.startsWith("server:"))         apiServer = l.substring(7).trim();
            else if (l.startsWith("token:"))     token = l.substring(6).trim();
            else if (l.contains("certificate-authority:"))
                  ca = l.split("certificate-authority:")[1].trim();
        }
        return new KubeConfig(apiServer, token, Path.of(ca));
    }

    private KubeConfig(String host, String token, Path caCert) {
        this.host = host;
        this.token = token;
        this.caCert= caCert;
    }
}
```

────────────────────────────────────────────────────────────────────────
4. Building a TLS-enabled HttpClient
────────────────────────────────────────────────────────────────────────
```
public static HttpClient buildClient(KubeConfig cfg) throws Exception {
    // load CA into a KeyStore
    CertificateFactory cf = CertificateFactory.getInstance("X.509");
    Certificate ca;
    try (InputStream in = Files.newInputStream(cfg.caCert)) {
        ca = cf.generateCertificate(in);
    }

    KeyStore ks = KeyStore.getInstance(KeyStore.getDefaultType());
    ks.load(null, null);
    ks.setCertificateEntry("ca", ca);

    TrustManagerFactory tmf =
        TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
    tmf.init(ks);

    SSLContext sslCtx = SSLContext.getInstance("TLS");
    sslCtx.init(null, tmf.getTrustManagers(), new SecureRandom());

    return HttpClient.newBuilder()
            .sslContext(sslCtx)
            .version(HttpClient.Version.HTTP_1_1)
            .connectTimeout(Duration.ofSeconds(10))
            .build();
}
```

────────────────────────────────────────────────────────────────────────
5. The Log client
────────────────────────────────────────────────────────────────────────
PodLogClient.java
```
public class PodLogClient {

    private final HttpClient http;
    private final KubeConfig cfg;

    public PodLogClient(HttpClient http, KubeConfig cfg) {
        this.http = http;
        this.cfg   = cfg;
    }

    // Synchronous            – fetch full logs and return as String
    public String getLogs(String ns, String pod, String container, LogOptions opts)
        throws IOException, InterruptedException {

        URI uri = buildUri(ns,pod,container,opts);
        HttpRequest req = HttpRequest.newBuilder(uri)
                .header("Authorization","Bearer "+cfg.token)
                .GET()
                .build();
        HttpResponse<String> resp =
             http.send(req, HttpResponse.BodyHandlers.ofString());

        if (resp.statusCode()!=200)
            throw new RuntimeException("K8s error "+resp.statusCode()+": "+resp.body());
        return resp.body();
    }

    // Asynchronous/streaming – call Consumer<String> for each log line
    public CompletableFuture<Void> followLogs(String ns, String pod,
                String container, LogOptions opts,
                Consumer<String> onLine, Consumer<Throwable> onError) {

        URI uri = buildUri(ns,pod,container,opts);
        HttpRequest req = HttpRequest.newBuilder(uri)
                .header("Authorization","Bearer "+cfg.token)
                .GET()
                .build();

        // we need the raw InputStream, so use ofInputStream()
        return http.sendAsync(req, HttpResponse.BodyHandlers.ofInputStream())
            .thenAcceptAsync(resp -> {
                if (resp.statusCode()!=200) {
                    onError.accept(new RuntimeException("HTTP "+resp.statusCode()));
                    return;
                }
                try (var reader =
                     new BufferedReader(new InputStreamReader(resp.body()))) {
                    String line;
                    while ((line = reader.readLine())!=null) {
                        onLine.accept(line);
                    }
                } catch (IOException ioe) {
                    onError.accept(ioe);
                }
            });
    }

    private URI buildUri(String ns,String pod,String container,LogOptions opts) {
        StringBuilder sb = new StringBuilder();
        sb.append(cfg.host)
          .append("/api/v1/namespaces/")
          .append(URLEncoder.encode(ns, StandardCharsets.UTF_8))
          .append("/pods/")
          .append(URLEncoder.encode(pod, StandardCharsets.UTF_8))
          .append("/log?container=")
          .append(URLEncoder.encode(container, StandardCharsets.UTF_8))
          .append(opts.toQuery());
        return URI.create(sb.toString());
    }
}
```

────────────────────────────────────────────────────────────────────────
6. End-to-end usage example
────────────────────────────────────────────────────────────────────────
```
public class Demo {
    public static void main(String[] args) throws Exception {
        // 1. build configuration
        KubeConfig cfg = (System.getenv("KUBERNETES_SERVICE_HOST")!=null)
                         ? KubeConfig.inCluster()
                         : KubeConfig.fromUserHome();

        // 2. client + helper
        HttpClient http = buildClient(cfg);
        PodLogClient logs = new PodLogClient(http, cfg);

        // 3a. One-shot (last 100 lines)
        String recent = logs.getLogs("default","my-pod","app",
                new LogOptions(false,false,null,100,false));
        System.out.println(recent);

        // 3b. Streaming
        logs.followLogs("default","my-pod","app",
                LogOptions.follow(),
                System.out::println,
                t -> {t.printStackTrace();});
        // keep JVM alive
        Thread.currentThread().join();
    }
}
```

────────────────────────────────────────────────────────────────────────
7. Things you may want to add before calling it a “library”
────────────────────────────────────────────────────────────────────────
• Parse kube-config properly (multiple contexts, client cert auth, exec auth).  
• Retry / reconnect when a follow-stream is cut.  
• Back-pressure / reactive wrapper (Flow.Publisher<String> or Reactor Flux).  
• Support multiplexing: aggregate logs of several pods with the same label 
  (first do a label-selector list-pods call, then open one stream per pod).  
• Add helper methods for “previous”, “sinceTime”, gzip compression, etc.  
• Package with Maven/Gradle and publish to internal registry.

────────────────────────────────────────────────────────────────────────
That’s it!  The code above demonstrates every moving part:
  – build a secure HttpClient  
  – hit the /log endpoint  
  – treat “follow=true” as an endless InputStream  

From here you can tune buffering, expose a nicer façade, or integrate into
existing frameworks such as Spring-Boot Actuator or Quarkus.

Why does nothing change?

1. The list that you render in +page.svelte comes from the load-function in +page.server.ts/+page.ts.
2. When you submit a SvelteKit “enhanced” form (`<form method="post">`) the client does **not** do a full page reload.  
   It sends an XHR, waits for the action to finish and keeps the current HTML.
3. The load-function is therefore **not executed again**, because as far as the router is concerned you are still on the same URL and nothing has told it that the data it cached is now stale.

So the note is deleted in the database, but the client keeps showing the array that was fetched before the deletion.

How to make the UI refresh

Pick one of the following patterns:

────────────────────────────────────────────────────────────

A) Redirect after the action  
(+page.server.ts)

```ts
import { redirect } from '@sveltejs/kit';

export const actions = {
	delete: async ({ request, locals }) => {
		const form = await request.formData();
		const id = form.get('id') as string;
		await db.note.delete({ where: { id } });

		// 303 forces a client-side navigation which re-runs load()
		throw redirect(303, '/notes');          // or the route you are on
	}
};
```

The navigation invalidates the current page automatically, the list is fetched again and the UI updates.

────────────────────────────────────────────────────────────

B) Stay on the same route and manually invalidate  
(+page.server.ts – return a normal result)

```ts
export const actions = {
	delete: async ({ request, locals }) => {
		const id = (await request.formData()).get('id') as string;
		await db.note.delete({ where: { id } });
		return { success: true };      // no redirect
	}
};
```

(+page.svelte)

```svelte
<script lang="ts">
	import { enhance } from '$app/forms';
	import { invalidateAll /* or invalidate('/notes') */ } from '$app/navigation';

	// re-run every load() on the current page when the action succeeds
	const enhanceDelete = enhance({
		result: async ({ result }) => {
			if (result.type === 'success') {
				await invalidateAll();      // or await invalidate('/notes');
			}
		}
	});
</script>

{#each data.notes as note}
	<form method="post" action="?/delete" use:enhance={enhanceDelete}>
		<input type="hidden" name="id" value={note.id} />
		<button type="submit">Delete</button>
	</form>
{/each}
```

`invalidateAll()` (or `invalidate('URL')`) tells SvelteKit that the previously cached data is stale, so it re-executes every load-function that provided data for the current page.

────────────────────────────────────────────────────────────

C) Use both – redirect for UX, invalidate for fine-grained control (for example inside a modal with no route change).

────────────────────────────────────────────────────────────

Key take-away

An action mutates data on the server; the client only sees the updated state when you force SvelteKit to rerun the load-function.  
Do this by redirecting or by calling `invalidate/invalidateAll` in the form’s `result` handler.

