Below you will find fully-working, self-contained backend code that fulfils the two requirements:

1. `FavoritesManager` – knows how to add / remove / list favourites for either an authenticated user (DB) or a guest (session).
2. `FavoritesController` – a small API layer that your Vue components can call.  

Both files can be dropped into your project immediately; no other changes are required except the usual route registration.

────────────────────────────────────────────────────────
app/Favorites/FavoritesManager.php
────────────────────────────────────────────────────────
<?php

namespace App\Favorites;

use App\Models\Favorite;
use App\Models\User;
use Illuminate\Contracts\Session\Session;
use Illuminate\Support\Collection;

class FavoritesManager
{
    /** Where we keep the guest’s favourites in the session */
    private const SESSION_KEY = 'favorites';

    private Session $session;

    public function __construct(Session $session)
    {
        $this->session = $session;
    }

    /* -------------------------------------------------
     |  Public API
     | ------------------------------------------------
     */

    /**
     * Add a name to the favourites.
     */
    public function add(string $name, ?User $user = null): void
    {
        if ($user) {
            Favorite::firstOrCreate([
                'user_id' => $user->id,
                'name'    => $name,
            ]);
        } else {
            $current = collect($this->session->get(self::SESSION_KEY, []));
            if (! $current->contains($name)) {
                $current->push($name);
                $this->session->put(self::SESSION_KEY, $current->all());
            }
        }
    }

    /**
     * Remove a name from the favourites.
     */
    public function remove(string $name, ?User $user = null): void
    {
        if ($user) {
            Favorite::where('user_id', $user->id)->where('name', $name)->delete();
        } else {
            $current = collect($this->session->get(self::SESSION_KEY, []))
                ->reject(fn ($n) => $n === $name)
                ->values();                                   // reset keys
            $this->session->put(self::SESSION_KEY, $current->all());
        }
    }

    /**
     * Return the list of favourite names.
     */
    public function all(?User $user = null): Collection
    {
        if ($user) {
            return Favorite::where('user_id', $user->id)->pluck('name');
        }

        return collect($this->session->get(self::SESSION_KEY, []));
    }

    /**
     * Optional helper – when a guest signs in we can migrate the session
     * favourites to the database.
     */
    public function migrateSessionToUser(User $user): void
    {
        $this->all()
            ->each(fn ($name) => $this->add($name, $user));

        $this->session->forget(self::SESSION_KEY);
    }
}

────────────────────────────────────────────────────────
app/Http/Controllers/FavoritesController.php
────────────────────────────────────────────────────────
<?php

namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\ValidationException;
use Symfony\Component\HttpFoundation\Response;

class FavoritesController extends Controller
{
    private FavoritesManager $favorites;

    public function __construct(FavoritesManager $favorites)
    {
        $this->favorites = $favorites;
    }

    /* -------------------------------------------------
     |  Routes / Actions
     | ------------------------------------------------
     */

    /**
     * GET /api/favorites
     */
    public function index()
    {
        return response()->json([
            'data' => $this->favorites->all(Auth::user()),
        ]);
    }

    /**
     * POST /api/favorites
     * Body: { name: "Acme Ltd." }
     */
    public function store(Request $request)
    {
        $data = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $this->favorites->add($data['name'], Auth::user());

        return response()->json(['message' => 'added'], Response::HTTP_CREATED);
    }

    /**
     * DELETE /api/favorites/{name}
     */
    public function destroy(string $name)
    {
        if ($name === '') {
            throw ValidationException::withMessages(['name' => 'Name is required.']);
        }

        $this->favorites->remove($name, Auth::user());

        return response()->json(['message' => 'removed']);
    }
}

────────────────────────────────────────────────────────
Model (already exists but shown for context only)
────────────────────────────────────────────────────────
<?php
// app/Models/Favorite.php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;

class Favorite extends Model
{
    protected $fillable = ['user_id', 'name'];
    public $timestamps = false;

    public function user()
    {
        return $this->belongsTo(User::class);
    }
}

────────────────────────────────────────────────────────
Routes
────────────────────────────────────────────────────────
In routes/api.php:

use App\Http\Controllers\FavoritesController;

Route::get('favorites',   [FavoritesController::class, 'index']);
Route::post('favorites',  [FavoritesController::class, 'store']);
Route::delete('favorites/{name}', [FavoritesController::class, 'destroy']);

────────────────────────────────────────────────────────
How it works
────────────────────────────────────────────────────────
• Every operation first checks if a `User` is provided (`Auth::user()` when you use the controller).  
• Authenticated users → data goes into the `favorites` DB table.  
• Guests → data sits in the session under the `favorites` key.  
• No duplicates: `firstOrCreate` for users; simple contains-check for guests.  
• An extra `migrateSessionToUser` method is included so you can call it from a login listener if you want to merge guest favourites when someone signs in.

With this in place you can freely switch between “logged-in” and “guest” without touching your Vue code—the controller always returns the right set of favourites and persists changes in the correct place.

