Below is a minimal-yet-complete example of an ERC-1155 contract that has one special “Creds” token‐type plus the usual multi-token flexibility of 1155.  
Key design choices

• OpenZeppelin 4.x is used for battle-tested 1155, AccessControl and supply helpers.  
• Creds (token-id = 0) are soul-bound (non-transferable between EOAs).  
• Any number of additional fungible / semi-fungible token-ids can still be created and behave normally unless they’re flagged as soul-bound.  
• A granular role model (ADMIN_ROLE, MINTER_ROLE) keeps mint / URI / config logic separate.  
• Per-id URIs are supported while still falling back to the base‐URI pattern required by ERC-1155.  

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/extensions/ERC1155Supply.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title Creds1155
 * @notice ERC-1155 implementation with a non-transferable “Creds” token-id
 *         + optional creation of additional token-ids (fungible, semi-fungible or soul-bound).
 */
contract Creds1155 is ERC1155Supply, AccessControl {
    /*───────────────────────────────────────────────────────────────────────────*/
    /* Roles                                                                    */
    /*───────────────────────────────────────────────────────────────────────────*/
    bytes32 public constant ADMIN_ROLE  = keccak256("ADMIN_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Constants / storage                                                      */
    /*───────────────────────────────────────────────────────────────────────────*/
    uint256 public constant CREDS = 0;               // Reserved id for creds
    mapping(uint256 => bool) public soulbound;       // id => non-transferable?
    mapping(uint256 => string) private _tokenURIs;   // optional id-specific uri

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Constructor                                                              */
    /*───────────────────────────────────────────────────────────────────────────*/
    constructor(string memory baseURI) ERC1155(baseURI) {
        _grantRole(ADMIN_ROLE,  msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);

        soulbound[CREDS] = true; // make creds non-transferable
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Minting logic                                                            */
    /*───────────────────────────────────────────────────────────────────────────*/
    function mintCreds(address to, uint256 amount, bytes calldata data)
        external
        onlyRole(MINTER_ROLE)
    {
        _mint(to, CREDS, amount, data);
    }

    // Generic mint (for any id, soul-bound or not)
    function mint(
        address to,
        uint256 id,
        uint256 amount,
        bytes calldata data
    ) external onlyRole(MINTER_ROLE) {
        _mint(to, id, amount, data);
    }

    function mintBatch(
        address to,
        uint256[] calldata ids,
        uint256[] calldata amounts,
        bytes calldata data
    ) external onlyRole(MINTER_ROLE) {
        _mintBatch(to, ids, amounts, data);
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Burn                                                                     */
    /*───────────────────────────────────────────────────────────────────────────*/
    function burn(
        address from,
        uint256 id,
        uint256 amount
    ) external {
        require(
            from == msg.sender || isApprovedForAll(from, msg.sender),
            "Creds1155: not authorised"
        );
        _burn(from, id, amount);
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Soul-bound enforcement                                                   */
    /*───────────────────────────────────────────────────────────────────────────*/
    // Block transfers of soul-bound ids except mint (from == 0x0) & burn (to == 0x0)
    function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal override(ERC1155Supply) {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);

        if (from != address(0) && to != address(0)) {
            for (uint256 i = 0; i < ids.length; i++) {
                require(!soulbound[ids[i]], "Creds1155: soul-bound");
            }
        }
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* URI management                                                           */
    /*───────────────────────────────────────────────────────────────────────────*/
    function setTokenURI(uint256 id, string calldata newURI)
        external
        onlyRole(ADMIN_ROLE)
    {
        _tokenURIs[id] = newURI;
        emit URI(newURI, id);
    }

    // ERC-1155 metadata lookup
    function uri(uint256 id) public view override returns (string memory) {
        string memory specific = _tokenURIs[id];
        if (bytes(specific).length > 0) {
            return specific;
        }
        // fallback to {baseURI}{id}.json
        return string.concat(super.uri(id), Strings.toString(id), ".json");
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Token-id creation helper                                                 */
    /*───────────────────────────────────────────────────────────────────────────*/
    /**
     * @notice Register a new token-id, optionally soul-bound, and emit its URI.
     *         No minting is performed here; MINTER_ROLE can mint afterwards.
     */
    function createTokenId(
        uint256 id,
        string calldata idURI,
        bool isSoulbound
    ) external onlyRole(ADMIN_ROLE) {
        require(bytes(_tokenURIs[id]).length == 0, "Creds1155: id exists");
        _tokenURIs[id] = idURI;
        soulbound[id] = isSoulbound;
        emit URI(idURI, id);
    }

    /*───────────────────────────────────────────────────────────────────────────*/
    /* Interface support                                                        */
    /*───────────────────────────────────────────────────────────────────────────*/
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC1155, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}
```

How to use

1. Deploy with a baseURI such as `https://ipfs.io/ipfs/Qm…/`  
2. `mintCreds(addr, 1, "")` – awards one non-transferable credential token.  
3. `createTokenId(42, "<uri>", false)` – registers id 42 as a normal transferable 1155 type, then `mint(addr, 42, 100, "")`.  
4. `createTokenId(99, "<uri>", true)` – registers id 99 as an additional soul-bound badge.  

Gas / security hints

• If you never need per-id URI override, strip `_tokenURIs` and rely on baseURI.  
• If creds should be truly singletons per address, cap `amount` to `1` inside `mintCreds`.  
• AccessControl roles can be swapped for ownable or multisig guarded calls as desired.  

