Below is a self–contained C/C++ design that can be compiled with Vitis HLS 2020.2 or later.  
It implements inference ( not training ) for a small fully–connected MNIST network

	784 → 128 → 64 → 10

using fixed-point arithmetic.  
All loops are statically-bound so the design can be fully-synthesised, and the
top function is exported to the FPGA through an AXI-4 Master for the
image and a lightweight AXI-4-Lite control interface.

Replace the “xxx …” comments with the trained weight / bias numbers that you
export from your favourite Python framework (script shown at the end).

File :  mnist_hls.h ( network parameters )
------------------------------------------------
#ifndef _MNIST_HLS_H_
#define _MNIST_HLS_H_

#include <ap_fixed.h>

#define N_IN   784
#define N_H1   128
#define N_H2   64
#define N_OUT  10

/* 16-bit fixed; 4 integer, 12 fractional bits */
typedef ap_fixed<16,4> data_t;

/* ===============  WEIGHTS & BIASES =================
 * The arrays are declared const so the synthesis tool
 * will map them automatically to BRAM/URAM or LUT ROM.
 *
 * Dump the values produced by python (see bottom) in
 * comma–separated form inside the braces.
 */
extern const data_t W1[N_H1][N_IN];
extern const data_t B1[N_H1];

extern const data_t W2[N_H2][N_H1];
extern const data_t B2[N_H2];

extern const data_t W3[N_OUT][N_H2];
extern const data_t B3[N_OUT];

#endif

File :  mnist_hls.cpp ( synthesizable source )
------------------------------------------------
#include "mnist_hls.h"
#include <hls_math.h>     // only used for expf in softmax (optional)

/********************************************
 * Hand-written helper layers
 *******************************************/
static void dense_1(
        const data_t  in_vec[N_IN],
        data_t        out_vec[N_H1])
{
#pragma HLS INLINE off
dense1_neuron:
    for (int n = 0; n < N_H1; n++) {
#pragma HLS PIPELINE II=1
        data_t acc = B1[n];          // start with bias
dense1_mult:
        for (int i = 0; i < N_IN; i++) {
            acc += W1[n][i] * in_vec[i];
        }
        /* ReLU in-place                                */
        out_vec[n] = (acc > 0) ? acc : (data_t)0;
    }
}

static void dense_2(
        const data_t  in_vec[N_H1],
        data_t        out_vec[N_H2])
{
#pragma HLS INLINE off
dense2_neuron:
    for (int n = 0; n < N_H2; n++) {
#pragma HLS PIPELINE II=1
        data_t acc = B2[n];
dense2_mult:
        for (int i = 0; i < N_H1; i++) {
            acc += W2[n][i] * in_vec[i];
        }
        out_vec[n] = (acc > 0) ? acc : (data_t)0;
    }
}

static void dense_3(
        const data_t  in_vec[N_H2],
        data_t        out_vec[N_OUT])
{
#pragma HLS INLINE off
dense3_neuron:
    for (int n = 0; n < N_OUT; n++) {
#pragma HLS PIPELINE II=1
        data_t acc = B3[n];
dense3_mult:
        for (int i = 0; i < N_H2; i++) {
            acc += W3[n][i] * in_vec[i];
        }
        /* final layer – keep logits, no activation */
        out_vec[n] = acc;
    }
}

/********************************************
 *   TOP-LEVEL – called by the PS
 *******************************************/
void mnist_top(   volatile data_t *image,   // 784 inputs in DDR
                  volatile int     *pred )  // single return value
{
#pragma HLS INTERFACE m_axi    port=image offset=slave bundle=gmem depth=784
#pragma HLS INTERFACE s_axilite port=image bundle=ctrl
#pragma HLS INTERFACE s_axilite port=pred  bundle=ctrl
#pragma HLS INTERFACE s_axilite port=return bundle=ctrl

    data_t in_buf [N_IN];
    data_t h1_buf [N_H1];
    data_t h2_buf [N_H2];
    data_t out_buf[N_OUT];

#pragma HLS ARRAY_PARTITION variable=in_buf  cyclic factor=16
#pragma HLS ARRAY_PARTITION variable=h1_buf  complete
#pragma HLS ARRAY_PARTITION variable=h2_buf  complete
#pragma HLS ARRAY_PARTITION variable=out_buf complete

/* ---------- 1) copy image from DRAM -------- */
load_image:
    for (int i = 0; i < N_IN; i++) {
#pragma HLS PIPELINE II=1
        in_buf[i] = image[i];   // one pixel per clock
    }

/* ---------- 2) network --------------------- */
    dense_1(in_buf,  h1_buf);
    dense_2(h1_buf,  h2_buf);
    dense_3(h2_buf,  out_buf);

/* ---------- 3) arg-max --------------------- */
    int     best_idx = 0;
    data_t  best_val = out_buf[0];

argmax_loop:
    for (int i = 1; i < N_OUT; i++) {
#pragma HLS PIPELINE
        if (out_buf[i] > best_val) {
            best_val = out_buf[i];
            best_idx = i;
        }
    }

    *pred = best_idx;
}

