<title>Object-Sprite Editor (JS)</title>
<style>
    body            {font-family:Arial,Helvetica,sans-serif;background:#222;color:#eee;margin:20px;}
    h1,h2           {margin:5px 0;}
    #toolbar        {margin:10px 0;}
    #spriteCanvas   {background:#fff;border:1px solid #555;cursor:crosshair;}
    button,input    {margin-right:6px;}
    textarea        {width:100%;height:120px;margin-top:4px;}
</style>
</head>
<body>
<h1>Object Sprite Editor</h1>

<div id="toolbar">
    Color <input type="color" id="colorPicker" value="#ff0000">
    <button id="clearBtn">Clear</button>
    <button id="exportBtn">Export JSON</button>
    <button id="importBtn">Import JSON</button>
    <input  type="file" id="jsonFile" accept=".json" style="display:none">
    <button id="downloadPNG">Download PNG</button>
</div>

<canvas id="spriteCanvas" width="512" height="512"></canvas>

<h2>JSON (output / import)</h2>
<textarea id="jsonOutput" readonly></textarea>

<script>
/* ====== Data model ====== */
class Sprite {
    constructor(cols, rows){
        this.cols  = cols;
        this.rows  = rows;
        this.pixels = new Array(cols*rows).fill(null); // null = transparent
    }
    #idx(x,y){ return y*this.cols + x; }
    setPixel(x,y,color){ this.pixels[this.#idx(x,y)] = color; }
    getPixel(x,y){ return this.pixels[this.#idx(x,y)]; }
    clear(){ this.pixels.fill(null); }
    toJSON(){
        return JSON.stringify({ cols:this.cols, rows:this.rows, pixels:this.pixels });
    }
    static fromJSON(json){
        const o = (typeof json === 'string') ? JSON.parse(json) : json;
        const s = new Sprite(o.cols,o.rows);
        s.pixels = o.pixels;
        return s;
    }
}

/* ====== Editor view/controller ====== */
class SpriteEditor {
    constructor(canvas, sprite, pixelSize){
        this.canvas      = canvas;
        this.ctx         = canvas.getContext('2d');
        this.sprite      = sprite;
        this.pixelSize   = pixelSize;
        this.currentColor= '#ff0000';
        this.isMouseDown = false;

        /* ––– Input ––– */
        canvas.addEventListener('mousedown', e => {this.isMouseDown=true; this.#paint(e);} );
        canvas.addEventListener('mousemove', e => {if(this.isMouseDown) this.#paint(e);} );
        window.addEventListener ('mouseup',   () => {this.isMouseDown=false;} );
        canvas.addEventListener('contextmenu',e => e.preventDefault());

        this.render();
    }
    setColor(c){ this.currentColor = c; }

    /* Draw one pixel (LMB → draw, RMB → erase) */
    #paint(e){
        const r   = this.canvas.getBoundingClientRect();
        const x   = Math.floor((e.clientX - r.left) / this.pixelSize);
        const y   = Math.floor((e.clientY - r.top)  / this.pixelSize);
        if (x<0||y<0||x>=this.sprite.cols||y>=this.sprite.rows) return;
        if (e.button === 2)       this.sprite.setPixel(x,y,null);      // RMB => erase
        else                      this.sprite.setPixel(x,y,this.currentColor);
        this.render();
    }

    /* Redraw whole canvas */
    render(){
        const s  = this.pixelSize, c = this.ctx;
        c.clearRect(0,0,this.canvas.width,this.canvas.height);

        /* Pixels */
        for(let y=0;y<this.sprite.rows;y++){
            for(let x=0;x<this.sprite.cols;x++){
                const col = this.sprite.getPixel(x,y);
                if(col){
                    c.fillStyle = col;
                    c.fillRect(x*s, y*s, s, s);
                }
            }
        }
        /* Grid */
        c.strokeStyle='rgba(0,0,0,.2)';
        for(let x=0;x<=this.sprite.cols;x++){
            c.beginPath(); c.moveTo(x*s,0); c.lineTo(x*s,this.canvas.height); c.stroke();
        }
        for(let y=0;y<=this.sprite.rows;y++){
            c.beginPath(); c.moveTo(0,y*s); c.lineTo(this.canvas.width,y*s); c.stroke();
        }
    }
}

/* ====== Boot-strap ====== */
const COLS=16, ROWS=16, PIXEL=32;
const canvas  = document.getElementById('spriteCanvas');
const sprite  = new Sprite(COLS, ROWS);
const editor  = new SpriteEditor(canvas, sprite, PIXEL);

/* ====== UI wiring ====== */
document.getElementById('colorPicker').addEventListener('input',e=>editor.setColor(e.target.value));

document.getElementById('clearBtn').addEventListener('click',()=>{
    sprite.clear(); editor.render();
});

const jsonBox = document.getElementById('jsonOutput');

/* --- Export to JSON + download --- */
document.getElementById('exportBtn').addEventListener('click',()=>{
    const data = sprite.toJSON();
    jsonBox.value = data;

    const blob = new Blob([data],{type:'application/json'});
    const url  = URL.createObjectURL(blob);
    const a    = Object.assign(document.createElement('a'), {href:url,download:'sprite.json'});
    a.click(); URL.revokeObjectURL(url);
});

/* --- Import JSON from file --- */
document.getElementById('importBtn').addEventListener('click',()=>document.getElementById('jsonFile').click());
document.getElementById('jsonFile').addEventListener('change',e=>{
    const file = e.target.files[0]; if(!file) return;
    const fr   = new FileReader();
    fr.onload  = ev=>{
        const loaded = Sprite.fromJSON(ev.target.result);
        Object.assign(sprite, loaded);   // copy cols,rows,pixels
        editor.render();
        jsonBox.value = loaded.toJSON();
    };
    fr.readAsText(file);
    e.target.value='';
});

/* --- Download as pixel-perfect PNG --- */
document.getElementById('downloadPNG').addEventListener('click',()=>{
    const off = document.createElement('canvas');
    off.width  = sprite.cols;
    off.height = sprite.rows;
    const ctx  = off.getContext('2d', {willReadFrequently:false});
    ctx.imageSmoothingEnabled = false;

    for(let y=0;y<sprite.rows;y++){
        for(let x=0;x<sprite.cols;x++){
            const col = sprite.getPixel(x,y);
            if(col){
                ctx.fillStyle = col;
                ctx.fillRect(x, y, 1, 1);
            }
        }
    }
    off.toBlob(b=>{
        const url = URL.createObjectURL(b);
        const a   = Object.assign(document.createElement('a'),{href:url,download:'sprite.png'});
        a.click(); URL.revokeObjectURL(url);
    },'image/png');
});
</script>
</body>
</html>
```

Features provided
• 16×16 grid (change COLS/ROWS/PIXEL constants to resize).  
• Left-click draws with selected color; right-click erases.  
• Live color picker, Clear, Export/Import (JSON) and PNG download.  
• Entire editor encapsulated by Sprite (data model) + SpriteEditor (UI/logic) classes, illustrating an object-oriented implementation in plain JavaScript.

Below is the simplest pattern that `vue-query` and Pinia play nicely together:  

1. Run the request with `useQuery`.  
2. Use the `select` option to keep only the fields you really need.  
3. In `onSuccess` (or `onSettled`) write the selected data into your global store with `$patch` (or any other Pinia action).

–––––––– 1.  Pinia store
```ts
// stores/session.ts
import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    // only the pieces of /get_session that we care about
    id:      null as number | null,
    name:    ''   as string,
    avatar:  ''   as string,
    // extra local flags
    loaded:  false,
    error:   false
  }),

  actions: {
    setSession (partial: Partial<this>) {
      this.$patch(partial)
    }
  }
})
```

–––––––– 2.  Query the endpoint and fill the store  
(You can do this in `App.vue`, a layout component, **or** inside a Pinia `setup` store itself.)

```vue
<script setup lang="ts">
import axios from 'axios'
import { useQuery } from '@tanstack/vue-query'
import { useSessionStore } from '@/stores/session'

// 1) get the store instance
const sessionStore = useSessionStore()

// 2) run the query
useQuery({
  queryKey: ['session'],
  queryFn : () => axios.get('/get_session').then(r => r.data),

  // 3) keep only what we want from the response
  select : (data) => ({
    id    : data.id,
    name  : data.username,        // maybe the backend calls it `username`
    avatar: data.profile_picture  // rename / keep only required keys
  }),

  // 4) write the selected data to Pinia
  onSuccess: (selected) => {
    sessionStore.setSession({ ...selected, loaded: true, error: false })
  },
  onError  : () => sessionStore.setSession({ error: true }),

  // optional tweaks
  staleTime: 1000 * 60 * 5,          // 5 min
  refetchOnWindowFocus: false
})
</script>
```

–––––––– 3.  Using it everywhere else
```vue
<script setup lang="ts">
import { useSessionStore } from '@/stores/session'

const { id, name, avatar, loaded, error } = storeToRefs(useSessionStore())
</script>
```
Now the whole application has a single source of truth for the session data that originated from `/get_session`, but you only stored the fields you were interested in.

