import FieldDropDown from "lib/hookForm/fieldDropDown"
import { ICompanyLogo } from "services/api/company/companyTypes"
import apiLoanQuery from "services/api/loan/apiLoanQuery"

interface IProps {
    forcePlaceLoanGuid?: string
    companyGuid?: string
}

export default function LoanLogoDropdown(props: IProps) {
    const { data: companyLogos } = apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery(props.forcePlaceLoanGuid)

    if (!!!companyLogos) return null

    const logoKeyValues = companyLogos.map((logo: ICompanyLogo) => ({
        key: logo.portfolioIdentifier,
        value: logo.logoDescription,
    }))

    return (
        <FieldDropDown label="Company Logo" name="portfolioIdentifier" data={logoKeyValues} placeholder="Select Logo" labelColSize={3} inputColSize={9} />
    )
}

output:
The compiler error you’re seeing is caused by the fact that  
apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery expects a string, but you might be passing undefined (because forcePlaceLoanGuid is optional).  
With RTK Query you have two good ways to resolve this:

1. Use the RTK Query skipToken (recommended)  
2. Supply an options object with { skip: boolean }.

Both approaches keep the hook “type‐safe” and prevent an unnecessary request when the GUID is missing.

Below are the two equivalent solutions plus a few small clean-ups (loading state, removing triple-bang, memoising the dropdown data).

─────────────────────────────────────────────────────────────
Option A – skipToken
─────────────────────────────────────────────────────────────
import React, { useMemo } from "react"
import { skipToken } from "@reduxjs/toolkit/query"
import FieldDropDown from "lib/hookForm/fieldDropDown"
import { ICompanyLogo } from "services/api/company/companyTypes"
import apiLoanQuery from "services/api/loan/apiLoanQuery"

interface IProps {
  forcePlaceLoanGuid?: string
  companyGuid?: string
}

export default function LoanLogoDropdown({ forcePlaceLoanGuid }: IProps) {
  const { data: companyLogos, isFetching } =
    apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery(
      forcePlaceLoanGuid ?? skipToken
    )

  // Optional loading / empty handling
  if (isFetching) return <div>Loading logos…</div>
  if (!companyLogos || companyLogos.length === 0) return null

  // Memoise so we don’t rebuild the array on every render
  const logoKeyValues = useMemo(
    () =>
      companyLogos.map((logo: ICompanyLogo) => ({
        key: logo.portfolioIdentifier,
        value: logo.logoDescription,
      })),
    [companyLogos]
  )

  return (
    <FieldDropDown
      label="Company Logo"
      name="portfolioIdentifier"
      data={logoKeyValues}
      placeholder="Select Logo"
      labelColSize={3}
      inputColSize={9}
    />
  )
}

─────────────────────────────────────────────────────────────
Option B – { skip: … } in the second argument
─────────────────────────────────────────────────────────────
const { data: companyLogos, isFetching } =
  apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery(
    forcePlaceLoanGuid as string,
    { skip: !forcePlaceLoanGuid }
  )

// …rest of the component identical…

Key take-aways
• The hook must receive either a string or skipToken / skip flag, never undefined.  
• skipToken comes from @reduxjs/toolkit/query (or ../query/react).  
• Triple-bang (!!!value) is the same as !value; replacing it improves readability.  
• useMemo is optional but avoids remapping the same array on every render.

Below is a compact, idiomatic, case-insensitive Rust helper that converts a month name (or its common 3-letter abbreviation, or a numeric string) to the corresponding month number.  
If the input is not recognized, it returns None.

```rust
/// Convert a month representation into its 1-based month number.
///
/// Recognised inputs (case-insensitive)
///   • Full names   -> "January", "February", …
///   • Abbreviations -> "Jan", "Feb", …
///   • Numeric text  -> "1", "01", … "12"
///
/// Returns:
///   Some(1-12) on success, or None on failure.
pub fn month_to_number<S: AsRef<str>>(month: S) -> Option<u8> {
    // Trim and canonicalise to lower case once
    let m = month.as_ref().trim().to_lowercase();

    match m.as_str() {
        "1" | "01" | "january"   | "jan" => Some(1),
        "2" | "02" | "february"  | "feb" => Some(2),
        "3" | "03" | "march"     | "mar" => Some(3),
        "4" | "04" | "april"     | "apr" => Some(4),
        "5" | "05" | "may"                   => Some(5),
        "6" | "06" | "june"      | "jun" => Some(6),
        "7" | "07" | "july"      | "jul" => Some(7),
        "8" | "08" | "august"    | "aug" => Some(8),
        "9" | "09" | "september" | "sep" | "sept" => Some(9),
        "10"        | "october"  | "oct" => Some(10),
        "11"        | "november" | "nov" => Some(11),
        "12"        | "december" | "dec" => Some(12),
        _ => None,
    }
}
```

Example usage
------------- 

```rust
fn main() {
    println!("{:?}", month_to_number("March"));    // Some(3)
    println!("{:?}", month_to_number("sep"));      // Some(9)
    println!("{:?}", month_to_number("12"));       // Some(12)
    println!("{:?}", month_to_number("FooMonth")); // None
}
```

Unit tests (optional)

```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_inputs() {
        assert_eq!(month_to_number("January"), Some(1));
        assert_eq!(month_to_number("feb"), Some(2));
        assert_eq!(month_to_number("  MAR "), Some(3));
        assert_eq!(month_to_number("9"), Some(9));
        assert_eq!(month_to_number("october"), Some(10));
    }

    #[test]
    fn test_invalid_input() {
        assert_eq!(month_to_number("Smarch"), None);
    }
}
```

Compile and run with:

```
cargo run
cargo test
```

The function is `no_std` friendly, needs only `core` and `alloc` for `String` allocation done by `to_lowercase()`, and covers most common human and machine-formatted month representations.

