Below is a self-contained, reasonably strong console implementation of Connect-4 written in Python 3.

• It supports Human vs Computer (default) or Human vs Human  
• The computer uses a depth-limited minimax + α/β pruning and a heuristic evaluation that makes it a challenging, yet fast, opponent.  
• No external libraries are required; just copy-paste into a file (e.g. connect4.py) and run with Python 3.

```python
#!/usr/bin/env python3
"""
Console Connect-4
  – 7 columns × 6 rows, first to align 4 (horiz/vert/diag) wins.
  – Human vs Computer (AI) or Human vs Human.

Author: ChatGPT demo – public domain
"""

import math
import random
import sys

ROWS, COLS = 6, 7
EMPTY = 0
HUMAN = 1
AI    = 2

MAX_DEPTH = 5        # search depth; increase for stronger AI (but slower)

# ────────────────────────── Board helpers ──────────────────────────
def create_board():
    return [[EMPTY for _ in range(COLS)] for _ in range(ROWS)]

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def is_valid_location(board, col):
    return board[0][col] == EMPTY

def get_next_open_row(board, col):
    for r in range(ROWS - 1, -1, -1):
        if board[r][col] == EMPTY:
            return r
    return None

def board_full(board):
    return all(board[0][c] != EMPTY for c in range(COLS))

def print_board(board):
    print("\n  " + " ".join(str(c) for c in range(COLS)))
    for r in range(ROWS):
        print(" |" + "|".join(" " if board[r][c] == EMPTY
                              else "X" if board[r][c] == HUMAN
                              else "O"
                              for c in range(COLS)) + "|")
    print(" +" + "-+" * COLS)

# ────────────────────────── Win detection ──────────────────────────
def winning_move(board, piece):
    # Horizontal
    for r in range(ROWS):
        for c in range(COLS - 3):
            if all(board[r][c + i] == piece for i in range(4)):
                return True
    # Vertical
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r + i][c] == piece for i in range(4)):
                return True
    # Positive diag (/)
    for r in range(ROWS - 3):
        for c in range(COLS - 3):
            if all(board[r + i][c + i] == piece for i in range(4)):
                return True
    # Negative diag (\)
    for r in range(3, ROWS):
        for c in range(COLS - 3):
            if all(board[r - i][c + i] == piece for i in range(4)):
                return True
    return False

# ────────────────────────── Heuristic evaluation ───────────────────
def evaluate_window(window, piece):
    score = 0
    opp_piece = HUMAN if piece == AI else AI

    if window.count(piece) == 4:
        score += 100
    elif window.count(piece) == 3 and window.count(EMPTY) == 1:
        score += 5
    elif window.count(piece) == 2 and window.count(EMPTY) == 2:
        score += 2

    if window.count(opp_piece) == 3 and window.count(EMPTY) == 1:
        score -= 4

    return score

def score_position(board, piece):
    score = 0

    # Center column preference
    center_array = [board[r][COLS // 2] for r in range(ROWS)]
    score += center_array.count(piece) * 3

    # Horizontal
    for r in range(ROWS):
        row_array = [board[r][c] for c in range(COLS)]
        for c in range(COLS - 3):
            window = row_array[c:c + 4]
            score += evaluate_window(window, piece)

    # Vertical
    for c in range(COLS):
        col_array = [board[r][c] for r in range(ROWS)]
        for r in range(ROWS - 3):
            window = col_array[r:r + 4]
            score += evaluate_window(window, piece)

    # Positive diag (/)
    for r in range(ROWS - 3):
        for c in range(COLS - 3):
            window = [board[r + i][c + i] for i in range(4)]
            score += evaluate_window(window, piece)

    # Negative diag (\)
    for r in range(ROWS - 3):
        for c in range(COLS - 3):
            window = [board[r + 3 - i][c + i] for i in range(4)]
            score += evaluate_window(window, piece)

    return score

def get_valid_locations(board):
    return [c for c in range(COLS) if is_valid_location(board, c)]

def pick_best_move(board, piece):
    # Greedy fallback (used for depth=0)
    valid_locations = get_valid_locations(board)
    best_score, best_col = -math.inf, random.choice(valid_locations)
    for col in valid_locations:
        row = get_next_open_row(board, col)
        temp = [r[:] for r in board]
        drop_piece(temp, row, col, piece)
        s = score_position(temp, piece)
        if s > best_score:
            best_score, best_col = s, col
    return best_col

# ───────────────────────────── Minimax ─────────────────────────────
def minimax(board, depth, alpha, beta, maximizing_player):
    valid_locations = get_valid_locations(board)
    is_terminal = winning_move(board, HUMAN) or winning_move(board, AI) or board_full(board)
    if depth == 0 or is_terminal:
        if is_terminal:
            if winning_move(board, AI):
                return (None, math.inf)
            elif winning_move(board, HUMAN):
                return (None, -math.inf)
            else:  # Draw
                return (None, 0)
        else:
            return (None, score_position(board, AI))

    if maximizing_player:
        value, best_col = -math.inf, random.choice(valid_locations)
        for col in valid_locations:
            row = get_next_open_row(board, col)
            b_copy = [r[:] for r in board]
            drop_piece(b_copy, row, col, AI)
            new_score = minimax(b_copy, depth - 1, alpha, beta, False)[1]
            if new_score > value:
                value, best_col = new_score, col
            alpha = max(alpha, value)
            if alpha >= beta:
                break
        return best_col, value
    else:
        value, best_col = math.inf, random.choice(valid_locations)
        for col in valid_locations:
            row = get_next_open_row(board, col)
            b_copy = [r[:] for r in board]
            drop_piece(b_copy, row, col, HUMAN)
            new_score = minimax(b_copy, depth - 1, alpha, beta, True)[1]
            if new_score < value:
                value, best_col = new_score, col
            beta = min(beta, value)
            if alpha >= beta:
                break
        return best_col, value

# ─────────────────────────── Game loop ─────────────────────────────
def human_move(board):
    valid = get_valid_locations(board)
    while True:
        try:
            col = int(input(f"Choose column {valid}: "))
            if col in valid:
                return col
        except (ValueError, EOFError):
            pass
        print("Invalid column. Try again.")

def main():
    print("CONNECT 4 (7×6)\n─ enter 'q' anytime to quit ─")
    mode = input("Play vs computer? (y/n) [y]: ").strip().lower()
    vs_ai = (mode != 'n')

    board = create_board()
    print_board(board)

    turn = random.choice([HUMAN, AI if vs_ai else HUMAN])  # who starts
    print(f"{'You' if turn == HUMAN else 'Computer' if vs_ai else 'Player 1'} starts!")

    while True:
        if turn == HUMAN or not vs_ai:
            col = human_move(board)
        else:
            print("Computer thinking…")
            col, _ = minimax(board, MAX_DEPTH, -math.inf, math.inf, True)

        row = get_next_open_row(board, col)
        piece = HUMAN if turn == HUMAN else AI
        drop_piece(board, row, col, piece)
        print_board(board)

        if winning_move(board, piece):
            if vs_ai:
                print("You win!" if piece == HUMAN else "Computer wins!")
            else:
                print(f"Player {piece} wins!")
            break
        if board_full(board):
            print("Game is a draw.")
            break

        # change turn
        if vs_ai:
            turn = AI if turn == HUMAN else HUMAN
        else:
            turn = 2 if turn == 1 else 1

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nGame aborted.")
```

How to play
1. Save the script as `connect4.py`.
2. Run with `python3 connect4.py`.
3. Enter a column number (0-6) when prompted.
4. First to connect four discs horizontally, vertically, or diagonally wins!

instruction:
help me remove column A  based on this code data vertical3;
	set vertical2;
format Treatment $Drug. Effectiveness $Effective. Sex $Sex. ;

output:
